(290377, 20749, 8488, '<td valign="top">If the glass were more the focus ... this is, however, a really good portrait of the kid.</td>', 'If the glass were more the focus ... this is, however, a really good portrait of the kid.', '2003-05-07 10:40:34.000000', NULL, 1),
(290378, 20670, 8488, '<td valign="top">I think I *have* one of those. :-&gt;</td>', 'I think I *have* one of those. :->', '2003-05-07 10:41:00.000000', NULL, 1),
(290379, 20730, 8488, '<td valign="top">The turtle''s the star. If the glass were the star, I''d have graded it better.</td>', 'The turtle''s the star. If the glass were the star, I''d have graded it better.', '2003-05-07 10:41:32.000000', NULL, 1),
(290381, 20458, 7953, '<td valign="top">How many messes did you make before you snapped this puppy?  Great idea, nice shot.</td>', 'How many messes did you make before you snapped this puppy?  Great idea, nice shot.', '2003-05-07 10:47:14.000000', NULL, 1),
