INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(291174, 20737, 6565, '<td valign="top">Wow, what a mood this sets.  I''m feeling sad for the broken whatever-it-was.  Good choice of focus, though the sky is a little bland.</td>', 'Wow, what a mood this sets.  I''m feeling sad for the broken whatever-it-was.  Good choice of focus, though the sky is a little bland.', '2003-05-07 18:23:46.000000', NULL, 1),
(291176, 20233, 6565, '<td valign="top">The dirt on the bowl in the left of the photo is very distracting.  Otherwise, the white-on-white concept is cool!</td>', 'The dirt on the bowl in the left of the photo is very distracting.  Otherwise, the white-on-white concept is cool!', '2003-05-07 18:24:28.000000', NULL, 1),
(291177, 20586, 6464, '<td valign="top">The perspective &amp; light makes it more interesting than the other shots of old glass bottles.</td>', 'The perspective & light makes it more interesting than the other shots of old glass bottles.', '2003-05-07 18:24:38.000000', NULL, 1),
(291178, 20825, 6565, '<td valign="top">I don''t see how this meets the challenge topic -- am I missing something?</td>', 'I don''t see how this meets the challenge topic -- am I missing something?', '2003-05-07 18:25:38.000000', NULL, 1),
(291180, 20734, 327, '<td valign="top">interesting shot, love all the bells, very cool find.</td>', 'interesting shot, love all the bells, very cool find.', '2003-05-07 18:26:23.000000', NULL, 1),
(291181, 20678, 6565, '<td valign="top">Interesting concept -- would have liked to maybe see a closeup on the face, or at least a clear view of both eyes.  That would have given this picture more mood, I think.</td>', 'Interesting concept -- would have liked to maybe see a closeup on the face, or at least a clear view of both eyes.  That would have given this picture more mood, I think.', '2003-05-07 18:26:33.000000', NULL, 1),
