(293350, 20819, 7889, '<td valign="top">This is a wonderful photo - how did you get this?</td>', 'This is a wonderful photo - how did you get this?', '2003-05-09 14:23:24.000000', NULL, 1),
(293351, 20759, 7780, '<td valign="top">I love the abrstractedness of glass and it was a great idea to add just one flower. I think you did a great job!</td>', 'I love the abrstractedness of glass and it was a great idea to add just one flower. I think you did a great job!', '2003-05-09 14:24:57.000000', NULL, 1),
